participation_query_template:
SELECT DISTINCT ?conflict ?country ?startDate ?endDate WHERE {
    hint:Query hint:optimizer "None" .

    ?conflictClass wdt:P279* wd:Q198 .
    ?conflict wdt:P31 ?conflictClass ;
            wdt:P710 ?country ;
            wdt:P580 ?startDate .

    OPTIONAL { ?conflict wdt:P582 ?endDate . }

    BIND(COALESCE(?endDate, "2026-12-31T23:59:59Z"^^xsd:dateTime) as ?effEndDate)
    FILTER(?startDate < "1725-01-01T00:00:00Z"^^xsd:dateTime && ?effEndDate >= "1700-01-01T00:00:00Z"^^xsd:dateTime)

    VALUES ?countryType { wd:Q3624078 wd:Q3024240 wd:Q6256 }
    ?countryClass wdt:P279* ?countryType .
    ?country wdt:P31 ?countryClass .

    MINUS {
        { SELECT DISTINCT ?excludedClass WHERE {
            VALUES ?excludedRoot { wd:Q20082270 wd:Q357104 }
            ?excludedClass wdt:P279* ?excludedRoot .
        } }
        ?conflict wdt:P31 ?excludedClass .
    }
}
ORDER BY ?conflict ?country ?startDate
LIMIT 5000
